        --danger-soft: #fff2f1;
        --success: #156c3f;
        --shadow: 0 28px 60px rgba(22, 32, 51, 0.14);
        --radius-xl: 24px;
        --radius-lg: 16px;
        --radius-md: 12px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(110, 139, 255, 0.28), transparent 32%),
          radial-gradient(circle at top right, rgba(57, 92, 255, 0.14), transparent 28%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        transform: translateY(-180%);
        transition: transform 0.2s ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 3rem 0 4rem;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
        gap: 2rem;
        align-items: start;
      }

      .hero-copy {
        padding: 2rem 0.5rem 0 0;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: rgba(57, 92, 255, 0.1);
        color: var(--primary-strong);
        font-size: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      .hero h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2.2rem, 4vw, 4rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .hero p {
        max-width: 34rem;
        margin: 0;
        font-size: 1.05rem;
        line-height: 1.7;
        color: var(--muted);
      }

      .support-points {
        display: grid;
        gap: 0.9rem;
        margin: 2rem 0 0;
        padding: 0;
        list-style: none;
      }

      .support-points li {
        display: flex;
        gap: 0.85rem;
        align-items: flex-start;
        color: var(--text);
      }

      .support-points span {
        display: inline-grid;
        place-items: center;
        width: 1.75rem;
        height: 1.75rem;
        flex: none;
        border-radius: 999px;
        background: rgba(57, 92, 255, 0.12);
        color: var(--primary-strong);
        font-weight: 800;
      }

      .form-panel {
        border: 1px solid rgba(204, 214, 229, 0.8);
        border-radius: var(--radius-xl);
        padding: 1.5rem;
        background: var(--surface);
        backdrop-filter: blur(18px);
        box-shadow: var(--shadow);
      }

      .panel-header h2 {
        margin: 0;
        font-size: 1.5rem;
        letter-spacing: -0.03em;
      }

      .panel-header p {
        margin: 0.65rem 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .required-note {
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .required-indicator {
        color: var(--danger);
        font-weight: 700;
      }

      form {
        display: grid;
        gap: 1rem;
        margin-top: 1.5rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 700;
        line-height: 1.4;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        padding: 0.95rem 1rem;
        background: var(--surface-strong);
        color: var(--text);
        font: inherit;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
      }

      input::placeholder {
        color: #8c98ad;
      }

      input:focus,
      button:focus,
      .skip-link:focus {
        outline: 3px solid rgba(57, 92, 255, 0.22);
        outline-offset: 2px;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(57, 92, 255, 0.08);
      }

      .field-hint,
      .field-error,
      .status-message {
        margin: 0;
        font-size: 0.94rem;
        line-height: 1.55;
      }

      .field-hint {
        color: var(--muted);
      }

      .field-error {
        color: var(--danger);
      }

      .field-error:empty,
      .status-message:empty {
        display: none;
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        background: var(--danger-soft);
      }

      .status-message {
        padding: 0.95rem 1rem;
        border-radius: var(--radius-md);
        background: rgba(57, 92, 255, 0.08);
        color: var(--primary-strong);
      }

      .status-message[data-status="success"] {
        background: rgba(21, 108, 63, 0.1);
        color: var(--success);
      }

      button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        width: 100%;
        border: 0;
        border-radius: 999px;
        padding: 1rem 1.25rem;
        background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
        box-shadow: 0 18px 30px rgba(57, 92, 255, 0.22);
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      @media (max-width: 840px) {
        .page-shell {
          padding-top: 1.5rem;
        }

        .hero {
          grid-template-columns: 1fr;
        }

        .hero-copy {
          padding-right: 0;
        }
      }

      @media (max-width: 480px) {
        .page-shell {
          width: min(100% - 1rem, 1120px);
        }

        .form-panel {
          padding: 1.25rem;
        }
      }

      @media (forced-colors: active) {
        .form-panel,
        input,
        button,
        .skip-link,
        .status-message {
          border: 1px solid CanvasText;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          autocomplete: "name",
          placeholder: "Avery Johnson",
          help: "",
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
          placeholder: "avery@example.com",
          help: "",
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          placeholder: "+1 (555) 123-4567",
          help: "Optional. Use digits only or a format like +1 (555) 123-4567.",
        },
      ];

      const escapeHtml = (value) =>
        String(value)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");

      const FormField = (field) => {
        const requiredMarker = field.required
          ? '<span class="required-indicator" aria-hidden="true">*</span>'
          : '<span class="field-hint">(optional)</span>';
        const helpId = field.help ? field.id + "-hint" : "";
        const errorId = field.id + "-error";
        const describedBy = [helpId, errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">${escapeHtml(field.label)} ${requiredMarker}</label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              ${field.required ? "required" : ""}
              autocomplete="${field.autocomplete}"
              placeholder="${escapeHtml(field.placeholder)}"
              aria-describedby="${describedBy}"
              aria-errormessage="${errorId}"
            />
            ${
              field.help
                ? `<p class="field-hint" id="${helpId}">${escapeHtml(field.help)}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}" aria-live="polite"></p>
          </div>
        `;
      };

      const SupportHighlights = () => `
        <ul class="support-points">
          <li><span>1</span><div>Tell us who you are so we can personalize the follow-up.</div></li>
          <li><span>2</span><div>Share the best email for updates and product guidance.</div></li>
          <li><span>3</span><div>Add a phone number if you want faster help for urgent requests.</div></li>
        </ul>
      `;

      const ContactForm = () => `
        <section class="form-panel" aria-labelledby="contact-form-title">
          <div class="panel-header">
            <h2 id="contact-form-title">Contact support</h2>
            <p>Send your details and our team will follow up with the next best step.</p>
            <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
          </div>
          <form id="support-form" novalidate>
            ${fields.map(FormField).join("")}
            <p class="status-message" id="form-status" aria-live="polite"></p>
            <button type="submit">Send request</button>
          </form>
        </section>
      `;

      const App = () => `
        <main id="main-content" class="page-shell" tabindex="-1">
          <section class="hero" aria-labelledby="page-title">
            <div class="hero-copy">
              <p class="eyebrow">Support</p>
              <h1 id="page-title">Talk to our team about your product questions.</h1>
              <p>
                Use the support form below to reach our specialists for onboarding guidance,
                account help, and fast answers when something needs attention.
              </p>
              ${SupportHighlights()}
            </div>
            ${ContactForm()}
          </section>
        </main>
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("support-form");
      const statusMessage = document.getElementById("form-status");

      const validators = {
        fullName(value) {
          const normalized = value.trim().replace(/\s+/g, " ");
          if (!normalized) {
            return "Error: Enter your full name.";
          }
          const parts = normalized.split(" ").filter(Boolean);
          if (parts.length < 2) {
            return "Error: Enter your first and last name.";
          }
          if (!/^[A-Za-zÀ-ÿ' -]+$/.test(normalized)) {
            return "Error: Use letters, spaces, apostrophes, or hyphens in your name.";
          }
          return "";
        },
        email(value) {
          const normalized = value.trim();
          if (!normalized) {
            return "Error: Enter your email address.";
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)) {
            return "Error: Enter a valid email address like name@example.com.";
          }
          return "";
        },
        phone(value) {
          const normalized = value.trim();
          if (!normalized) {
            return "";
          }
          if (!/^[+\d()\s-]+$/.test(normalized)) {
            return "Error: Use only digits, spaces, parentheses, hyphens, or a leading plus sign.";
          }
          const digits = normalized.replace(/\D/g, "");
          if (digits.length < 10 || digits.length > 15) {
            return "Error: Enter a phone number with 10 to 15 digits.";
          }
          return "";
        },
      };

      const getFieldElements = (name) => {
        const input = document.getElementById(name);
        const error = document.getElementById(name + "-error");
        return { input, error };
      };

      const setFieldState = (name, errorMessage) => {
        const { input, error } = getFieldElements(name);
        error.textContent = errorMessage;
        if (errorMessage) {
          input.setAttribute("aria-invalid", "true");
        } else {
          input.removeAttribute("aria-invalid");
        }
      };

      const validateField = (name) => {
        const { input } = getFieldElements(name);
        const errorMessage = validators[name](input.value);
        setFieldState(name, errorMessage);
        return errorMessage;
      };

      fields.forEach((field) => {
        const { input } = getFieldElements(field.id);
        input.addEventListener("blur", () => validateField(field.id));
        input.addEventListener("input", () => {
          if (input.getAttribute("aria-invalid") === "true") {
            validateField(field.id);
          }
          if (statusMessage.dataset.status) {
            statusMessage.textContent = "";
            statusMessage.dataset.status = "";
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const errors = fields
          .map((field) => ({
            id: field.id,
            message: validateField(field.id),
          }))
          .filter((result) => result.message);

        if (errors.length > 0) {
          statusMessage.dataset.status = "error";
          statusMessage.textContent = "Please correct the highlighted fields and try again.";
          document.getElementById(errors[0].id).focus();
          return;
        }

        statusMessage.dataset.status = "success";
        statusMessage.textContent = "Thanks. Your support request is ready to send.";
        form.reset();
        fields.forEach((field) => setFieldState(field.id, ""));
      });
    </script>
  </body>
</html>
