    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          autocomplete: "name",
          placeholder: "Avery Johnson",
          help: "",
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
          placeholder: "avery@example.com",
          help: "",
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          placeholder: "+1 (555) 123-4567",
          help: "Optional. Use digits only or a format like +1 (555) 123-4567.",
        },
      ];

      const escapeHtml = (value) =>
        String(value)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");

      const FormField = (field) => {
        const requiredMarker = field.required
          ? '<span class="required-indicator" aria-hidden="true">*</span>'
          : '<span class="field-hint">(optional)</span>';
        const helpId = field.help ? field.id + "-hint" : "";
        const errorId = field.id + "-error";
        const describedBy = [helpId, errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">${escapeHtml(field.label)} ${requiredMarker}</label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              ${field.required ? "required" : ""}
              autocomplete="${field.autocomplete}"
              placeholder="${escapeHtml(field.placeholder)}"
              aria-describedby="${describedBy}"
              aria-errormessage="${errorId}"
            />
            ${
              field.help
                ? `<p class="field-hint" id="${helpId}">${escapeHtml(field.help)}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}" aria-live="polite"></p>
          </div>
        `;
      };

      const SupportHighlights = () => `
        <ul class="support-points">
          <li><span>1</span><div>Tell us who you are so we can personalize the follow-up.</div></li>
          <li><span>2</span><div>Share the best email for updates and product guidance.</div></li>
          <li><span>3</span><div>Add a phone number if you want faster help for urgent requests.</div></li>
        </ul>
      `;

      const ContactForm = () => `
        <section class="form-panel" aria-labelledby="contact-form-title">
          <div class="panel-header">
            <h2 id="contact-form-title">Contact support</h2>
            <p>Send your details and our team will follow up with the next best step.</p>
            <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
          </div>
          <form id="support-form" novalidate>
            ${fields.map(FormField).join("")}
            <p class="status-message" id="form-status" aria-live="polite"></p>
            <button type="submit">Send request</button>
          </form>
        </section>
      `;

