     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>
     <script>
       const fields = [
         {
           id: "fullName",
           label: "Full name",
           type: "text",
           required: true,
           autocomplete: "name",
           placeholder: "Avery Johnson",
           help: "",
         },
         {
           id: "email",
           label: "Email address",
           type: "email",
           required: true,
           autocomplete: "email",
           placeholder: "avery@example.com",
           help: "",
         },
         {
           id: "phone",
           label: "Phone number",
           type: "tel",
           required: false,
           autocomplete: "tel",
           placeholder: "+1 (555) 123-4567",
           help: "Optional. Use digits only or a format like +1 (555) 123-4567.",
         },
       ];

       const escapeHtml = (value) =>
         String(value)
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;")
           .replace(/"/g, "&quot;")
           .replace(/'/g, "&#39;");

       const FormField = (field) => {
         const requiredMarker = field.required
           ? '<span class="required-indicator" aria-hidden="true">*</span>'
           : '<span class="field-hint">(optional)</span>';
         const helpId = field.help ? field.id + "-hint" : "";
         const errorId = field.id + "-error";
         const describedBy = [helpId, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${field.id}">${escapeHtml(field.label)} ${requiredMarker}</label>
             <input
               id="${field.id}"
               name="${field.id}"
               type="${field.type}"
               ${field.required ? "required" : ""}
               autocomplete="${field.autocomplete}"
               placeholder="${escapeHtml(field.placeholder)}"
               aria-describedby="${describedBy}"
               aria-errormessage="${errorId}"
             />
             ${
               field.help
                 ? `<p class="field-hint" id="${helpId}">${escapeHtml(field.help)}</p>`
                 : ""
             }
             <p class="field-error" id="${errorId}" aria-live="polite"></p>
           </div>
         `;
       };

       const SupportHighlights = () => `
         <ul class="support-points">
           <li><span>1</span><div>Tell us who you are so we can personalize the follow-up.</div></li>
           <li><span>2</span><div>Share the best email for updates and product guidance.</div></li>
           <li><span>3</span><div>Add a phone number if you want faster help for urgent requests.</div></li>
         </ul>
       `;

       const ContactForm = () => `
         <section class="form-panel" aria-labelledby="contact-form-title">
           <div class="panel-header">
             <h2 id="contact-form-title">Contact support</h2>
             <p>Send your details and our team will follow up with the next best step.</p>
             <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
           </div>
           <form id="support-form" novalidate>
             ${fields.map(FormField).join("")}
             <p class="status-message" id="form-status" aria-live="polite"></p>
             <button type="submit">Send request</button>
           </form>
         </section>
       `;

       const App = () => `
         <main id="main-content" class="page-shell" tabindex="-1">
           <section class="hero" aria-labelledby="page-title">
             <div class="hero-copy">
               <p class="eyebrow">Support</p>
               <h1 id="page-title">Talk to our team about your product questions.</h1>
               <p>
                 Use the support form below to reach our specialists for onboarding guidance,
                 account help, and fast answers when something needs attention.
               </p>
               ${SupportHighlights()}
             </div>
             ${ContactForm()}
           </section>
         </main>
       `;

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("support-form");
       const statusMessage = document.getElementById("form-status");

       const validators = {
         fullName(value) {
           const normalized = value.trim().replace(/\s+/g, " ");
           if (!normalized) {
             return "Error: Enter your full name.";
           }
           const parts = normalized.split(" ").filter(Boolean);
           if (parts.length < 2) {
             return "Error: Enter your first and last name.";
           }
           if (!/^[A-Za-zÀ-ÿ' -]+$/.test(normalized)) {
             return "Error: Use letters, spaces, apostrophes, or hyphens in your name.";
           }
           return "";
         },
         email(value) {
           const normalized = value.trim();
           if (!normalized) {
             return "Error: Enter your email address.";
           }
           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)) {
             return "Error: Enter a valid email address like name@example.com.";
           }
           return "";
         },
         phone(value) {
           const normalized = value.trim();
           if (!normalized) {
             return "";
           }
           if (!/^[+\d()\s-]+$/.test(normalized)) {
             return "Error: Use only digits, spaces, parentheses, hyphens, or a leading plus sign.";
           }
           const digits = normalized.replace(/\D/g, "");
           if (digits.length < 10 || digits.length > 15) {
             return "Error: Enter a phone number with 10 to 15 digits.";
           }
           return "";
         },
       };

       const getFieldElements = (name) => {
         const input = document.getElementById(name);
         const error = document.getElementById(name + "-error");
         return { input, error };
       };

       const setFieldState = (name, errorMessage) => {
         const { input, error } = getFieldElements(name);
         error.textContent = errorMessage;
         if (errorMessage) {
           input.setAttribute("aria-invalid", "true");
         } else {
           input.removeAttribute("aria-invalid");
         }
       };

       const validateField = (name) => {
         const { input } = getFieldElements(name);
         const errorMessage = validators[name](input.value);
         setFieldState(name, errorMessage);
         return errorMessage;
       };

       fields.forEach((field) => {
         const { input } = getFieldElements(field.id);
         input.addEventListener("blur", () => validateField(field.id));
         input.addEventListener("input", () => {
           if (input.getAttribute("aria-invalid") === "true") {
             validateField(field.id);
           }
           if (statusMessage.dataset.status) {
             statusMessage.textContent = "";
             statusMessage.dataset.status = "";
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const errors = fields
           .map((field) => ({
             id: field.id,
             message: validateField(field.id),
           }))
           .filter((result) => result.message);

         if (errors.length > 0) {
           statusMessage.dataset.status = "error";
           statusMessage.textContent = "Please correct the highlighted fields and try again.";
           document.getElementById(errors[0].id).focus();
           return;
         }

         statusMessage.dataset.status = "success";
         statusMessage.textContent = "Thanks. Your support request is ready to send.";
         form.reset();
         fields.forEach((field) => setFieldState(field.id, ""));
       });
     </script>
